    &.active {
      border-color: #cf866b;
      background: #fff8f5;
    }
    
    .method-icon {
      width: 0.6rem;
      height: 0.6rem;
      margin-right: 10px;
    }
    
    .method-info {
      flex: 1;
      
      .method-name {
        font-size: 0.32rem;
        color: #333;
        font-weight: 500;
      }
      
      .method-desc {
        font-size: 0.24rem;
        color: #999;
        margin-top: 4px;
      }
    }
    
    .method-check {
      width: 0.4rem;
      height: 0.4rem;
      border-radius: 50%;
      border: 1px solid #ddd;
      display: flex;
      align-items: center;
      justify-content: center;
      
      .check-icon {
        color: #cf866b;
        font-size: 0.28rem;
        font-weight: bold;
      }
    }
    
    &.active .method-check {
      border-color: #cf866b;
      background: #cf866b;
      
      .check-icon {
        color: #fff;
      }
    }
  }
}

// 二维码样式
.qrcode-box {
  text-align: center;
  padding: 20px;
  
  .qrcode-img {
    width: 200px;
    height: 200px;
    border: 1px solid #eee;
    border-radius: 8px;
  }
  
  .qrcode-tip {
    margin-top: 10px;
    font-size: 0.28rem;
    color: #666;
  }
}

.lasthg {
  display: flex;
  align-items: center;
  font-size: 0.33rem;
  color: #a5a9b3;
  padding: 0.2rem 0;
}

.bans {
  background-image: linear-gradient(180deg, #fff, #f9fcff);
  width: 90%;
  margin: 0 auto;
  padding: 20px;
  border-radius: 20px;
  box-sizing: border-box;
  margin-bottom: 20px;
  p {
    display: flex;
    justify-content: space-between;
    align-items: center;
    .frists {
      width: 70px;
    }
    .sdsw {
      flex: 1;
    }
    .copy {
      color: #069b71;
    }
  }
}
</style>



