      <div class="vip-levels">
        <div 
          v-for="(item, index) in 10" 
          :key="index"
          :class="(index + 1) == vipTab ? 'vip-level-item active' : 'vip-level-item'"
          @click="changvipTab(index + 1)"
        >
          VIP{{ index + 1 }}
