            { icon: '/static/image/vip-icon-4.png', name: '生日礼金', value: '388元' },
            { icon: '/static/image/vip-icon-5.png', name: '晋级礼金', value: '688元' },
            { icon: '/static/image/vip-icon-6.png', name: '专属活动', value: '每日专属' },
          ]
        },
        7: {
          title: '星耀至尊特权',
          list: [
            { icon: '/static/image/vip-icon-1.png', name: '返水比例', value: '0.9%' },
            { icon: '/static/image/vip-icon-2.png', name: '提款额度', value: '15万/日' },
            { icon: '/static/image/vip-icon-3.png', name: '专属客服', value: '专属经理' },
            { icon: '/static/image/vip-icon-4.png', name: '生日礼金', value: '688元' },
            { icon: '/static/image/vip-icon-5.png', name: '晋级礼金', value: '1288元' },
            { icon: '/static/image/vip-icon-6.png', name: '专属活动', value: '定制活动' },
            { icon: '/static/image/vip-icon-7.png', name: '豪华旅游', value: '年度旅游' },
          ]
        },
        8: {
